import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c2_blocks.1.act_k10.npy')); b=-20.8715
c=torch.tensor(np.load('c_eval.npy')[:3000]); xi=torch.tensor(np.load('xi_eval.npy')[:3000])
cs=np.load('track_cs.npy'); med=np.load('track_med.npy'); cn=c.numpy()
def lab(a):
    an=np.arctan2(a[:,1],a[:,0]); d=np.degrees(np.angle(np.exp(1j*(an-np.interp(cn,cs,med)))))
    return (np.abs(d)<15)&(np.linalg.norm(a,axis=1)>1.8)
def run(M=None,const=None,lo=0,hi=0,thr=0.0):
    x=xi.clone(); fired=torch.zeros(len(x),dtype=torch.bool)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.1.act",),count=False)
        if lo<=k<hi:
            s=a["blocks.1.act"]@w+b; f=s>thr; fired|=f
            add=(x@M.T if M is not None else 0)+(const if const is not None else 0)
            v=v+f.float()[:,None]*add
        x=x-v/20
    return x.numpy(),fired.numpy()
with torch.no_grad():
    a0,_=run(); T=lab(a0)
    # reference ring stats: radius distribution of good actions
    r0=np.linalg.norm(a0,axis=1)
    res=[]
    for sgn,name in ((1,'cw'),(-1,'ccw')):
        for mag in (1.5,3,5):
            M=torch.tensor([[0,1.],[-1.,0]])*sgn*(-mag)  # v add = -mag*R x => dx=+mag*R x/20
            for lo,hi in ((2,10),(4,12),(6,12),(8,13)):
                for thr in (0,5):
                    a1,f=run(M=M,lo=lo,hi=hi,thr=thr); T1=lab(a1); r1=np.linalg.norm(a1,axis=1)
                    mv=np.linalg.norm(a1-a0,axis=1)>0.3
                    res.append((name,mag,lo,hi,thr,round(T1[T].mean(),3),round(mv[~T].mean(),3),round(T1[~T].mean(),4),round(((r1<1.8)&~(r0<1.8)).mean(),4)))
    for x in sorted(res,key=lambda z:z[5]+2*z[6])[:25]: print(x)

