import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c2_blocks.1.act_k10.npy')); b=-20.8715
c=torch.tensor(np.load('c_eval.npy')[:3000]); xi=torch.tensor(np.load('xi_eval.npy')[:3000])
cs=np.load('track_cs.npy'); med=np.load('track_med.npy'); cn=c.numpy()
def lab(a):
    an=np.arctan2(a[:,1],a[:,0]); d=np.degrees(np.angle(np.exp(1j*(an-np.interp(cn,cs,med)))))
    return (np.abs(d)<15)&(np.linalg.norm(a,axis=1)>1.8)
def run(M=None,lo=0,hi=0,thr=0.0):
    x=xi.clone()
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.1.act",),count=False)
        if lo<=k<hi:
            s=a["blocks.1.act"]@w+b; f=s>thr
            v=v+f.float()[:,None]*(x@M.T)
        x=x-v/20
    return x.numpy()
def hist(a,keep):
    an=np.degrees(np.arctan2(a[:,1],a[:,0])); H,_,_=np.histogram2d(an[keep],cn[keep],bins=(24,4),range=((-180,180),(0,1)))
    H=H/H.sum(0,keepdims=True); return H
with torch.no_grad():
    a0=run(); T=lab(a0); H0=hist(a0,~T)
    R=torch.tensor([[0,-1.],[1.,0]])
    res=[]
    for ma in (20,35,50):
        m=np.array([np.cos(np.radians(ma)),np.sin(np.radians(ma))]); P=torch.tensor(np.eye(2)-np.outer(m,m),dtype=torch.float32)
        for nm,B in (('cw',R),('perp',P*(-1.0))):
            for mag in (3,5,8,12):
                for lo,hi in ((0,6),(2,8),(4,10),(6,10),(4,12)):
                    if nm=='cw' and ma!=35: continue
                    a1=run(M=B*mag,lo=lo,hi=hi); T1=lab(a1)
                    tv=0.5*np.abs(hist(a1,~T1)-H0).sum(0).mean()
                    mv=(np.linalg.norm(a1-a0,axis=1)>0.3)[~T].mean()
                    res.append((nm,ma,mag,lo,hi,round(T1[T].mean(),3),round(tv,4),round(mv,4)))
    res=[z for z in res if z[5]<0.35]
    for x in sorted(res,key=lambda z:z[6])[:15]: print(x)
    print([z for z in res if z[0]=='cw' and z[3]==4 and z[4]==12])
